import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/** UUID primary key, generated by Postgres (DAT-08). */
export const id = () => uuid("id").primaryKey().default(sql`gen_random_uuid()`);

/** created_at / updated_at as timestamptz (DAT-14). updated_at is maintained by a trigger. */
export const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
};

/** Append-only tables use occurred_at instead of created/updated (DAT-14). */
export const occurredAt = () =>
  timestamp("occurred_at", { withTimezone: true }).notNull().defaultNow();
